impl Document {
    pub(crate) fn compare_can_frame(
        &self,
        other: &Document,
        a: &CanFrame,
        b: &CanFrame,
        path: &str,
    ) -> Result<(), String> {
        self.compare_frame(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_can_frame_triggering(
        &self,
        other: &Document,
        a: &CanFrameTriggering,
        b: &CanFrameTriggering,
        path: &str,
    ) -> Result<(), String> {
        self.compare_frame_triggering(other, a.base(), b.base(), path)?;
        let list_a = a.get_absolutely_scheduled_timings();
        let list_b = b.get_absolutely_scheduled_timings();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: ABSOLUTELY_SCHEDULED_TIMINGS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .ttcan_absolutely_scheduled_timings
                .get(*x)
                .ok_or_else(|| {
                    format!(
                        "{path}.ABSOLUTELY_SCHEDULED_TIMINGS[{index}]: id not found in own arena"
                    )
                })?;
            let y = other
                .ttcan_absolutely_scheduled_timings
                .get(*y)
                .ok_or_else(|| {
                    format!(
                        "{path}.ABSOLUTELY_SCHEDULED_TIMINGS[{index}]: id not found in other arena"
                    )
                })?;
            self.compare_ttcan_absolutely_scheduled_timing(
                other,
                x,
                y,
                &format!("{path}.ABSOLUTELY_SCHEDULED_TIMINGS[{index}]"),
            )?;
        }
        if a.get_can_addressing_mode() != b.get_can_addressing_mode() {
            return Err(format!("{path}: CAN_ADDRESSING_MODE mismatch"));
        }
        if a.get_can_frame_rx_behavior() != b.get_can_frame_rx_behavior() {
            return Err(format!("{path}: CAN_FRAME_RX_BEHAVIOR mismatch"));
        }
        if a.get_can_frame_tx_behavior() != b.get_can_frame_tx_behavior() {
            return Err(format!("{path}: CAN_FRAME_TX_BEHAVIOR mismatch"));
        }
        if a.get_can_xl_frame_triggering_props() != b.get_can_xl_frame_triggering_props() {
            return Err(format!("{path}: CAN_XL_FRAME_TRIGGERING_PROPS mismatch"));
        }
        if a.get_identifier() != b.get_identifier() {
            return Err(format!("{path}: IDENTIFIER mismatch"));
        }
        if a.get_j1939requestable() != b.get_j1939requestable() {
            return Err(format!("{path}: J1939REQUESTABLE mismatch"));
        }
        if a.get_rx_identifier_range() != b.get_rx_identifier_range() {
            return Err(format!("{path}: RX_IDENTIFIER_RANGE mismatch"));
        }
        if a.get_rx_mask() != b.get_rx_mask() {
            return Err(format!("{path}: RX_MASK mismatch"));
        }
        if a.get_tx_mask() != b.get_tx_mask() {
            return Err(format!("{path}: TX_MASK mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_can_xl_frame_triggering_props(
        &self,
        _other: &Document,
        a: &CanXlFrameTriggeringProps,
        b: &CanXlFrameTriggeringProps,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_acceptance_field() != b.get_acceptance_field() {
            return Err(format!("{path}: ACCEPTANCE_FIELD mismatch"));
        }
        if a.get_priority_id() != b.get_priority_id() {
            return Err(format!("{path}: PRIORITY_ID mismatch"));
        }
        if a.get_sdu_type() != b.get_sdu_type() {
            return Err(format!("{path}: SDU_TYPE mismatch"));
        }
        if a.get_vcid() != b.get_vcid() {
            return Err(format!("{path}: VCID mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_rx_identifier_range(
        &self,
        _other: &Document,
        a: &RxIdentifierRange,
        b: &RxIdentifierRange,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_lower_can_id() != b.get_lower_can_id() {
            return Err(format!("{path}: LOWER_CAN_ID mismatch"));
        }
        if a.get_upper_can_id() != b.get_upper_can_id() {
            return Err(format!("{path}: UPPER_CAN_ID mismatch"));
        }
        Ok(())
    }
}
